function setWorkspaceTab(tab){workspaceTab=tab;const reader=tab==='reader';$('#readerPanel').hidden=!reader;$('#boardPanel').hidden=reader;for(const [id,active] of [['readerTab',reader],['boardTab',!reader]]){const button=$('#'+id);button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;}if(activeBookId)setRoute();}
function renderNotes(){const b=books.find(b=>b.id===activeBookId);if(!b)return;const notes=workspaceOf(b).notes;$('#noteCount').textContent=notes.length+' '+(notes.length===1?'note':'notes');$('#notesList').innerHTML=notes.length?notes.map(n=>`<article class="workspace-note"><h3>${escapeHTML(n.title||'Untitled note')}</h3><p>${escapeHTML(n.body)}</p><div class="note-actions"><button data-edit-note="${escapeHTML(n.id)}">Edit note</button><button data-delete-note="${escapeHTML(n.id)}">Delete note</button></div></article>`).join(''):'<div class="notes-empty"><h3>No notes yet.</h3><p>Collect a thought, a clue or a character. Notes belong only to this book.</p></div>';}
function resetNoteForm(){editingNoteId=null;$('#noteForm').reset();$('#noteFormTitle').textContent='New note';$('#cancelNote').hidden=true;}
$('#backToLibrary').onclick=()=>backToLibrary();$('#customizeBook').onclick=()=>openCustomize(activeBookId);
$('#attachEPUB').onclick=()=>{const b=books.find(b=>b.id===activeBookId);if(!b)return;if(b.file&&!confirm('Replace this book’s attached EPUB? The previous file will be replaced. Your book title, author, appearance and notes will be preserved.'))return;chooseEPUB(b.id)};
$('#readerTab').onclick=()=>setWorkspaceTab('reader');$('#boardTab').onclick=()=>setWorkspaceTab('board');
$('.workspace-tabs').addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tab=e.key==='Home'?'reader':e.key==='End'?'board':workspaceTab==='reader'?'board':'reader';setWorkspaceTab(tab);$(tab==='reader'?'#readerTab':'#boardTab').focus();}});
$('#createForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,title=form.elements.title.value.trim();if(!title)return message('Please enter a book title.');const submit=form.querySelector('[type="submit"]');submit.disabled=true;try{const b=newBookRecord(title,form.elements.author.value.trim());await persist(b);books.push(b);page=Math.floor((books.length-1)/SHELF_CAPACITY);$('#createDialog').close();backToLibrary();message('Book created. Select its spine to open your workspace.')}catch{message('Could not create this book. Please check browser storage and try again.',true)}finally{submit.disabled=false}};
$('#noteForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,body=form.elements.noteBody.value.trim();if(!body)return message('Please enter some note text.');const bookId=activeBookId,noteId=editingNoteId,note={title:form.elements.noteTitle.value.trim(),body},submit=form.querySelector('[type="submit"]');submit.disabled=true;try{await updateBook(bookId,current=>saveBookNote(current,note,noteId));if(activeBookId===bookId){resetNoteForm();renderNotes();}message('Note saved on this device.')}catch(e){message(e.message||'Could not save this note.',true)}finally{submit.disabled=false}};
$('#cancelNote').onclick=resetNoteForm;
$('#notesList').addEventListener('click',async e=>{const edit=e.target.closest('[data-edit-note]'),remove=e.target.closest('[data-delete-note]'),bookId=activeBookId;
  if(edit){const book=books.find(b=>b.id===bookId),note=workspaceOf(book).notes.find(n=>n.id===edit.dataset.editNote);if(!note)return;editingNoteId=note.id;$('#noteForm').elements.noteTitle.value=note.title||'';$('#noteForm').elements.noteBody.value=note.body||'';$('#noteFormTitle').textContent='Edit note';$('#cancelNote').hidden=false;$('#noteForm').elements.noteBody.focus();}
  if(remove&&confirm('Delete this note? This cannot be undone.')){try{await updateBook(bookId,current=>deleteBookNote(current,remove.dataset.deleteNote));if(activeBookId===bookId){if(editingNoteId===remove.dataset.deleteNote)resetNoteForm();renderNotes();}message('Note deleted.')}catch{message('Could not delete this note.',true)}}
});
window.addEventListener('hashchange',()=>{if(db)restoreRoute()});
